@js:
var mode = 'novel';
try { var m = java.get("mode"); if (m && m != 'null' && m != '') mode = String(m); } catch(e) {}
try {
    if (mode === 'audio') {
        var au = java.getElements("#read-audio");
        if (au && au.length > 0) {
            var src = au[0].attr("src");
            src ? src : java.getString(".read-body p@text");
        } else { java.getString(".read-body p@text"); }
    } else if (mode === 'comic') {
        var imgs = java.getElements(".read-body p img");
        var r = [];
        if (imgs && imgs.length > 0) {
            for (var i = 0; i < imgs.length; i++) {
                var s = imgs[i].attr("src");
                if (s && (s.indexOf("gallery") > -1 || s.indexOf("upload.xchina") > -1)) r.push('<img src="' + s + '">');
            }
        }
        r.length > 0 ? r.join("\n") : java.getString(".read-body p@text");
    } else {
        java.getString(".read-body p@text");
    }
} catch(e) { "<p>正文解析失败: " + e + "</p>"; }

