function switchMode(mode) {
    java.put("mode", mode);
    java.put("sub", "cat");
    try { infoMap["sub"] = "分类"; infoMap.save(); } catch(e) {}
    var names = {novel:'小说', audio:'有声', comic:'漫画'};
    java.longToast('已切换到：' + names[mode] + '模式');
    java.refreshExplore();
}
